import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the function f defined for x > 0 with the properties f({scale_a}x) = {scale_a} f(x) for all x > 0, and for x in the base interval [{base_l}, {scale_a}{base_l}] it is given by f(x) = (({scale_a}-1){base_l})/2 - |x - (({scale_a}+1){base_l})/2|. Let N = {target_n}. If the positive real solutions of f(x) = f(N) are listed in increasing order as x_1 < x_2 < x_3 < ..., compute the sum x_1 + x_2 + ... + x_{count_r}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We sample parameters so that:
# - a in {3,4,5,6}
# - L is even (ensures integrality of apex and height)
# - choose y0 in (L, aL) integer, not at center, with S = h - |y0 - mid| > 0 and a*S <= h (so t>=1 and problem nontrivial)
# - choose n moderately sized; N = y0 * a^n ensures the reduction lands exactly in the base interval
# - choose r between 3 and 8 to enforce a multi-term sum
while True:
    a = rng.randint(3, 6)
    # even L
    L = rng.randrange(4, 100, 2)
    h = (a - 1) * L // 2
    mid = (a + 1) * L // 2
    # Build candidate y0 list: strictly inside (L, aL), not at mid, and with a*S <= h and S>0
    y_candidates = []
    for y0 in range(L + 1, a * L):
        if y0 == mid:
            continue
        S = h - abs(y0 - mid)
        if S > 0 and a * S <= h:
            y_candidates.append(y0)
    if not y_candidates:
        continue
    y0 = rng.choice(y_candidates)
    n_exp = rng.randint(3, 8)
    N = y0 * (a ** n_exp)
    r = rng.randint(3, 8)
    # All constraints satisfied by construction
    return {
        'scale_a': a,
        'base_l': L,
        'target_n': N,
        'count_r': r
    }

    def verifier(assign):
# Verify structure
try:
    a = int(assign['scale_a'])
    L = int(assign['base_l'])
    N = int(assign['target_n'])
    r = int(assign['count_r'])
except Exception:
    # Missing or invalid fields
    return (False, None)

# Basic validations
if a < 3 or L <= 0 or N <= 0 or r < 1:
    # invalid domain
    return (False, None)
if L % 2 != 0:
    # need even L for integrality of base triangle
    return (False, None)

# Define base parameters
h = (a - 1) * L // 2
mid = (a + 1) * L // 2

# Compute n such that y0 = N / a^n lies in [L, aL]
# Do this using integer comparisons to avoid float issues
# Find n so that L * a^n <= N <= aL * a^n
n = 0
# increase n until N <= aL * a^n
while N > (a * L) * (a ** n):
    n += 1
# if too small, decrease n until N >= L * a^n
while N < L * (a ** n):
    n -= 1

# Now compute scaled constants without dividing
H = (a ** n) * h
M = (a ** n) * mid
S_n = H - abs(N - M)  # equals a^n * S, where S = h - |y0 - mid|

# Validate non-degenerate instance
if S_n <= 0 or S_n >= H:
    # Degenerate (either apex S=h -> infinite descent causing no minimum; or endpoint S=0)
    return (False, None)

# Ensure difficulty: we want at least one scale drop (t >= 1), i.e., a*S <= h
# This translates to a * S_n <= H because S_n = a^n S and H = a^n h
if a * S_n > H:
    # not sufficiently nontrivial
    return (False, None)

# Compute t = max { t >= 0 : a^t * S <= h } using scaled integers: a^t * S_n <= H
t = 0
# Grow t as long as inequality holds
while (a ** (t + 1)) * S_n <= H:
    t += 1

# minimal exponent m0 for the smallest solution
m0 = n - t

# Build the first r solutions in increasing order using the derived closed forms
xs = []
for j in range(r):
    if j % 2 == 0:
        # even index -> x_min at scale m
        m = m0 + (j // 2)
        xj = S_n + (a ** m) * L
    else:
        # odd index -> x_max at same scale m
        m = m0 + (j // 2)
        xj = (a ** (m + 1)) * L - S_n
    xs.append(xj)

# Check strict monotonicity and positivity
for i in range(1, len(xs)):
    if not (xs[i] > xs[i - 1] > 0):
        return (False, None)

# Compute the sum
answer = sum(xs)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

